package main

import (
	"fmt"
	"strings"
)

const charset = "qpzry9x8gf2tvdw0s3jn54khce6mua7l"

var gen = []int{0x3b6a57b2, 0x26508e6d, 0x1ea119fa, 0x3d4233dd, 0x2a1462b3}

func polymod(values []byte) int {
	chk := 1
	for _, v := range values {
		b := chk >> 25
		chk = (chk&0x1ffffff)<<5 ^ int(v)
		for i := 0; i < 5; i++ {
			if (b>>i)&1 == 1 {
				chk ^= gen[i]
			}
		}
	}
	return chk
}

func hrpExpand(hrp string) []byte {
	v := []byte{}
	for _, c := range []byte(hrp) {
		v = append(v, c>>5)
	}
	v = append(v, 0)
	for _, c := range []byte(hrp) {
		v = append(v, c&31)
	}
	return v
}

func convertBits(data []byte, frombits, tobits uint, pad bool) ([]byte, error) {
	var acc, bits uint
	ret := []byte{}
	maxv := byte((1 << tobits) - 1)
	for _, value := range data {
		if value>>frombits != 0 {
			return nil, fmt.Errorf("invalid data range")
		}
		acc = acc<<frombits | uint(value)
		bits += frombits
		for bits >= tobits {
			bits -= tobits
			ret = append(ret, byte(acc>>bits)&maxv)
		}
	}
	if pad {
		if bits > 0 {
			ret = append(ret, byte(acc<<(tobits-bits))&maxv)
		}
	} else if bits >= frombits || byte(acc<<(tobits-bits))&maxv != 0 {
		return nil, fmt.Errorf("invalid padding")
	}
	return ret, nil
}

func Encode(hrp string, data []byte) (string, error) {
	values, err := convertBits(data, 8, 5, true)
	if err != nil {
		return "", err
	}
	vals := append(hrpExpand(hrp), values...)
	polymodv := polymod(append(vals, []byte{0, 0, 0, 0, 0, 0}...)) ^ 1
	var sb strings.Builder
	sb.WriteString(hrp)
	sb.WriteString("1")
	for _, v := range values {
		sb.WriteByte(charset[v])
	}
	for i := 0; i < 6; i++ {
		sb.WriteByte(charset[byte(polymodv>>uint(5*(5-i)))&31])
	}
	return sb.String(), nil
}

func Decode(s string) (string, []byte, error) {
	lower := strings.ToLower(s)
	upper := strings.ToUpper(s)
	if s != lower && s != upper {
		return "", nil, fmt.Errorf("mixed case")
	}
	s = lower
	pos := strings.LastIndex(s, "1")
	if pos < 1 || pos+7 > len(s) {
		return "", nil, fmt.Errorf("invalid separator")
	}
	hrp := s[:pos]
	data := []byte{}
	for _, c := range s[pos+1:] {
		idx := strings.IndexRune(charset, c)
		if idx < 0 {
			return "", nil, fmt.Errorf("invalid char %q", c)
		}
		data = append(data, byte(idx))
	}
	if polymod(append(hrpExpand(hrp), data...)) != 1 {
		return "", nil, fmt.Errorf("bad checksum")
	}
	out, err := convertBits(data[:len(data)-6], 5, 8, false)
	if err != nil {
		return "", nil, err
	}
	return hrp, out, nil
}
EOF
