package main

import (
	"crypto/ecdh"
	"encoding/hex"
	"fmt"
	"os"
	"strings"
)

func main() {
	sk := "AGE-SECRET-KEY-1N9JEPW6DWJ0ZQUDX63F5A03GX8QUW7PXDE39N8UYF82VZ9PC8UFS3M7XA9"
	hrp, data, err := Decode(sk)
