	fmt.Println("derived pub:", enc)
	fmt.Println("expected   : age1lvyvwawkr0mcnnnncaghunadrqkmuf9e6507x9y920xxpp866cnql7dp2z")
	// also re-encode secret
	re, _ := Encode(strings.ToLower("AGE-SECRET-KEY-"), data)
	fmt.Println("reenc secret:", strings.ToUpper(re))
}
