// Package sha3 implements the Keccak permutation and the SHA-3 and SHAKE
// functions standardized in FIPS 202. Only the pieces needed by ML-KEM are
// provided: SHA3-256, SHA3-512, SHAKE-128 and SHAKE-256.
package sha3

import "encoding/binary"

// roundConstants are the ι step constants for the 24 rounds of Keccak-f[1600].
var roundConstants = [24]uint64{
	0x0000000000000001, 0x0000000000008082, 0x800000000000808a, 0x8000000080008000,
	0x000000000000808b, 0x0000000080000001, 0x8000000080008081, 0x8000000000008009,
	0x000000000000008a, 0x0000000000000088, 0x0000000080008009, 0x000000008000000a,
	0x000000008000808b, 0x800000000000008b, 0x8000000000008089, 0x8000000000008003,
	0x8000000000008002, 0x8000000000000080, 0x000000000000800a, 0x800000008000000a,
	0x8000000080008081, 0x8000000000008080, 0x0000000080000001, 0x8000000080008008,
}

// rotationOffsets[x][y] is the ρ step rotation for lane (x, y).
var rotationOffsets = [5][5]uint{
	{0, 36, 3, 41, 18},
	{1, 44, 10, 45, 2},
	{62, 6, 43, 15, 61},
	{28, 55, 25, 21, 56},
	{27, 20, 39, 8, 14},
}

func rotl(v uint64, n uint) uint64 {
	if n == 0 {
		return v
	}
	return v<<n | v>>(64-n)
}

// permute applies Keccak-f[1600] to the state, which is indexed as a[x+5*y].
func permute(a *[25]uint64) {
	var c [5]uint64
	var d [5]uint64
	var b [25]uint64
	for round := 0; round < 24; round++ {
		// θ
		for x := 0; x < 5; x++ {
			c[x] = a[x] ^ a[x+5] ^ a[x+10] ^ a[x+15] ^ a[x+20]
		}
		for x := 0; x < 5; x++ {
			d[x] = c[(x+4)%5] ^ rotl(c[(x+1)%5], 1)
		}
		for x := 0; x < 5; x++ {
			for y := 0; y < 5; y++ {
				a[x+5*y] ^= d[x]
			}
		}
		// ρ and π
		for x := 0; x < 5; x++ {
			for y := 0; y < 5; y++ {
				b[y+5*((2*x+3*y)%5)] = rotl(a[x+5*y], rotationOffsets[x][y])
			}
		}
		// χ
		for x := 0; x < 5; x++ {
			for y := 0; y < 5; y++ {
				a[x+5*y] = b[x+5*y] ^ (^b[(x+1)%5+5*y] & b[(x+2)%5+5*y])
			}
		}
		// ι
		a[0] ^= roundConstants[round]
	}
}

// state is a sponge over Keccak-f[1600].
type state struct {
	a       [25]uint64
	buf     []byte // pending input or unread output, a view into storage
	storage [200]byte

	rate    int
	dsbyte  byte
	outLen  int
	queuing bool // true while absorbing, false once squeezing has begun
}

func (s *state) reset() {
	for i := range s.a {
		s.a[i] = 0
	}
	s.buf = s.storage[:0]
	s.queuing = true
}

func (s *state) BlockSize() int { return s.rate }
func (s *state) Size() int      { return s.outLen }

func (s *state) permuteBlock(block []byte) {
	for i := 0; i < len(block)/8; i++ {
		s.a[i] ^= binary.LittleEndian.Uint64(block[i*8:])
	}
	permute(&s.a)
}

func (s *state) Write(p []byte) (int, error) {
	if !s.queuing {
		panic("sha3: write to sponge after read")
	}
	n := len(p)
	for len(p) > 0 {
		if len(s.buf) == 0 && len(p) >= s.rate {
			s.permuteBlock(p[:s.rate])
			p = p[s.rate:]
			continue
		}
		want := s.rate - len(s.buf)
		if want > len(p) {
			want = len(p)
		}
		s.buf = append(s.buf, p[:want]...)
		p = p[want:]
		if len(s.buf) == s.rate {
			s.permuteBlock(s.buf)
			s.buf = s.storage[:0]
		}
	}
	return n, nil
}

// pad finishes absorption, applying the domain separation byte and the
// pad10*1 rule, and switches the sponge to squeezing.
func (s *state) pad() {
	block := make([]byte, s.rate)
	copy(block, s.buf)
	block[len(s.buf)] = s.dsbyte
	block[s.rate-1] |= 0x80
	s.permuteBlock(block)
	s.queuing = false
	s.fill()
}

// fill copies a full rate's worth of state into the output buffer.
func (s *state) fill() {
	s.buf = s.storage[:s.rate]
	for i := 0; i < s.rate/8; i++ {
		binary.LittleEndian.PutUint64(s.buf[i*8:], s.a[i])
	}
}

func (s *state) Read(out []byte) (int, error) {
	if s.queuing {
		s.pad()
	}
	n := len(out)
	for len(out) > 0 {
		if len(s.buf) == 0 {
			permute(&s.a)
			s.fill()
		}
		c := copy(out, s.buf)
		s.buf = s.buf[c:]
		out = out[c:]
	}
	return n, nil
}

func (s *state) Sum(b []byte) []byte {
	// Sum must not modify the sponge, so operate on a copy.
	dup := *s
	dup.buf = dup.storage[:len(s.buf)]
	out := make([]byte, dup.outLen)
	dup.Read(out)
	return append(b, out...)
}

