package sha3

import "hash"

// New256 returns a SHA3-256 hash.
func New256() hash.Hash {
	s := &state{rate: 136, dsbyte: 0x06, outLen: 32}
	s.reset()
	return s
}

// New512 returns a SHA3-512 hash.
func New512() hash.Hash {
	s := &state{rate: 72, dsbyte: 0x06, outLen: 64}
	s.reset()
	return s
}

// Sum256 returns the SHA3-256 digest of data.
func Sum256(data []byte) [32]byte {
	var out [32]byte
	h := New256()
	h.Write(data)
	h.Sum(out[:0])
	copy(out[:], h.Sum(nil))
	return out
}

// Sum512 returns the SHA3-512 digest of data.
func Sum512(data []byte) [64]byte {
	var out [64]byte
	h := New512()
	h.Write(data)
	copy(out[:], h.Sum(nil))
	return out
}

// SHAKE is an extendable output function. Write absorbs input; Read squeezes
// an arbitrary amount of output. Writing after the first Read panics.
type SHAKE struct {
	s state
}

// NewSHAKE128 returns a SHAKE-128 XOF.
func NewSHAKE128() *SHAKE {
	x := &SHAKE{s: state{rate: 168, dsbyte: 0x1f, outLen: 32}}
	x.s.reset()
	return x
}

// NewSHAKE256 returns a SHAKE-256 XOF.
func NewSHAKE256() *SHAKE {
	x := &SHAKE{s: state{rate: 136, dsbyte: 0x1f, outLen: 64}}
	x.s.reset()
	return x
}

func (x *SHAKE) Write(p []byte) (int, error) { return x.s.Write(p) }
func (x *SHAKE) Read(p []byte) (int, error)  { return x.s.Read(p) }

// Reset returns the XOF to its initial state.
func (x *SHAKE) Reset() { x.s.reset() }

// ShakeSum128 writes n bytes of SHAKE-128(data) into out.
func ShakeSum128(out, data []byte) {
	x := NewSHAKE128()
	x.Write(data)
	x.Read(out)
}

// ShakeSum256 writes len(out) bytes of SHAKE-256(data) into out.
func ShakeSum256(out, data []byte) {
	x := NewSHAKE256()
	x.Write(data)
	x.Read(out)
}

