package sha3

import (
	"encoding/hex"
	"testing"
)

func TestSHA3(t *testing.T) {
	for _, tc := range []struct {
		fn   func([]byte) string
		in   string
		want string
	}{
		{func(b []byte) string { s := Sum256(b); return hex.EncodeToString(s[:]) }, "",
			"a7ffc6f8bf1ed76651c14756a061d662f580ff4de43b49fa82d80a4b80f8434a"},
		{func(b []byte) string { s := Sum256(b); return hex.EncodeToString(s[:]) }, "abc",
			"3a985da74fe225b2045c172d6bd390bd855f086e3e9d525b46bfe24511431532"},
		{func(b []byte) string { s := Sum512(b); return hex.EncodeToString(s[:]) }, "",
			"a69f73cca23a9ac5c8b567dc185a756e97c982164fe25859e0d1dcc1475c80a615b2123af1f5f94c11e3e9402c3ac558f500199d95b6d3e301758586281dcd26"},
		{func(b []byte) string { s := Sum512(b); return hex.EncodeToString(s[:]) }, "abc",
			"b751850b1a57168a5693cd924b6b096e08f621827444f70d884f5d0240d2712e10e116e9192af3c91a7ec57647e3934057340b4cf408d5a56592f8274eec53f0"},
	} {
		if got := tc.fn([]byte(tc.in)); got != tc.want {
			t.Errorf("hash(%q) = %s, want %s", tc.in, got, tc.want)
		}
	}
}

func TestSHAKE(t *testing.T) {
	out := make([]byte, 32)
	ShakeSum128(out, nil)
	if got, want := hex.EncodeToString(out), "7f9c2ba4e88f827d616045507605853ed73b8093f6efbc88eb1a6eacfa66ef26"; got != want {
		t.Errorf("SHAKE128('') = %s, want %s", got, want)
	}
	ShakeSum256(out, nil)
	if got, want := hex.EncodeToString(out), "46b9dd2b0ba88d13233b3feb743eeb243fcd52ea62b81b82b50c27646ed5762f"; got != want {
		t.Errorf("SHAKE256('') = %s, want %s", got, want)
	}
	// Streaming reads must match a single large read.
	x := NewSHAKE128()
	x.Write([]byte("hello world"))
	big := make([]byte, 500)
	x.Read(big)
	y := NewSHAKE128()
	y.Write([]byte("hello"))
	y.Write([]byte(" world"))
	inc := make([]byte, 0, 500)
	for len(inc) < 500 {
		b := make([]byte, 7)
		y.Read(b)
		inc = append(inc, b...)
	}
	if hex.EncodeToString(big) != hex.EncodeToString(inc[:500]) {
		t.Error("incremental SHAKE output differs")
	}
}

func TestSumDoesNotMutate(t *testing.T) {
	h := New256()
	h.Write([]byte("abc"))
	a := hex.EncodeToString(h.Sum(nil))
	b := hex.EncodeToString(h.Sum(nil))
	if a != b {
		t.Errorf("Sum is not idempotent: %s != %s", a, b)
	}
	if a != "3a985da74fe225b2045c172d6bd390bd855f086e3e9d525b46bfe24511431532" {
		t.Errorf("wrong digest %s", a)
	}
}

