// Package aead implements the ChaCha20-Poly1305 AEAD from RFC 8439, along
// with the raw ChaCha20 stream cipher and Poly1305 one-time authenticator it
// is built from.
package aead

import (
	"crypto/subtle"
	"encoding/binary"
	"errors"
	"math/bits"
)

const (
	// KeySize is the size of a ChaCha20-Poly1305 key in bytes.
	KeySize = 32
	// NonceSize is the size of a ChaCha20-Poly1305 nonce in bytes.
	NonceSize = 12
	// TagSize is the size of a Poly1305 authentication tag in bytes.
	TagSize = 16
)

// ErrOpen is returned when an AEAD ciphertext fails authentication.
var ErrOpen = errors.New("message authentication failed")

var sigma = [4]uint32{0x61707865, 0x3320646e, 0x79622d32, 0x6b206574}

func qr(a, b, c, d *uint32) {
	*a += *b
	*d ^= *a
	*d = bits.RotateLeft32(*d, 16)
	*c += *d
	*b ^= *c
	*b = bits.RotateLeft32(*b, 12)
	*a += *b
	*d ^= *a
	*d = bits.RotateLeft32(*d, 8)
	*c += *d
	*b ^= *c
	*b = bits.RotateLeft32(*b, 7)
}

// chachaBlock computes the 64-byte keystream block for the given counter.
func chachaBlock(out *[64]byte, key *[8]uint32, counter uint32, nonce *[3]uint32) {
	var s [16]uint32
	s[0], s[1], s[2], s[3] = sigma[0], sigma[1], sigma[2], sigma[3]
	copy(s[4:12], key[:])
	s[12] = counter
	s[13], s[14], s[15] = nonce[0], nonce[1], nonce[2]

	v := s
	for i := 0; i < 10; i++ {
		qr(&v[0], &v[4], &v[8], &v[12])
		qr(&v[1], &v[5], &v[9], &v[13])
		qr(&v[2], &v[6], &v[10], &v[14])
		qr(&v[3], &v[7], &v[11], &v[15])
		qr(&v[0], &v[5], &v[10], &v[15])
		qr(&v[1], &v[6], &v[11], &v[12])
		qr(&v[2], &v[7], &v[8], &v[13])
		qr(&v[3], &v[4], &v[9], &v[14])
	}
	for i := range v {
		binary.LittleEndian.PutUint32(out[i*4:], v[i]+s[i])
	}
}

// XORKeyStream XORs src into dst with the ChaCha20 keystream generated from
// key and nonce, starting at the given block counter. dst and src may alias.
func XORKeyStream(dst, src []byte, key []byte, nonce []byte, counter uint32) {
	var k [8]uint32
	for i := 0; i < 8; i++ {
		k[i] = binary.LittleEndian.Uint32(key[i*4:])
	}
	var n [3]uint32
	for i := 0; i < 3; i++ {
		n[i] = binary.LittleEndian.Uint32(nonce[i*4:])
	}
	var block [64]byte
	for len(src) > 0 {
		chachaBlock(&block, &k, counter, &n)
		counter++
		n := len(src)
		if n > 64 {
			n = 64
		}
		for i := 0; i < n; i++ {
			dst[i] = src[i] ^ block[i]
		}
		dst, src = dst[n:], src[n:]
	}
}

// poly1305 is the Poly1305 one-time authenticator over a 130-bit accumulator
// held in three 44/44/42-bit limbs.
type poly1305 struct {
	r0, r1, r2 uint64 // clamped key, radix 2^44
	s1, s2     uint64 // 20*r1, 20*r2 for the reduction
	h0, h1, h2 uint64 // accumulator
	pad        [16]byte
	buf        [16]byte
	n          int
}

func newPoly1305(key []byte) *poly1305 {
	p := new(poly1305)
	t0 := binary.LittleEndian.Uint64(key[0:8])
	t1 := binary.LittleEndian.Uint64(key[8:16])
	// r &= 0x0ffffffc0ffffffc0ffffffc0fffffff, then split into 44/44/42 bits.
	p.r0 = t0 & 0xffc0fffffff
	p.r1 = ((t0 >> 44) | (t1 << 20)) & 0xfffffc0ffff
	p.r2 = (t1 >> 24) & 0x00ffffffc0f
	p.s1 = p.r1 * 20
	p.s2 = p.r2 * 20
	copy(p.pad[:], key[16:32])
	return p
}

// blocks absorbs full 16-byte blocks; hibit is 1 for message blocks and 0 for
// the implicitly shorter final block, which supplies its own high bit.
func (p *poly1305) blocks(m []byte, hibit uint64) {
	for len(m) >= 16 {
		t0 := binary.LittleEndian.Uint64(m[0:8])
		t1 := binary.LittleEndian.Uint64(m[8:16])
		p.h0 += t0 & 0xfffffffffff
		p.h1 += ((t0 >> 44) | (t1 << 20)) & 0xfffffffffff
		p.h2 += ((t1 >> 24) & 0x3ffffffffff) | hibit<<40
		p.mul()
		m = m[16:]
	}
}

func (p *poly1305) mul() {
	// h *= r mod 2^130-5, using 128-bit intermediate products.
	hi, lo := bits.Mul64(p.h0, p.r0)
	h, l := bits.Mul64(p.h1, p.s2)
	lo, c := bits.Add64(lo, l, 0)
	hi += h + c
	h, l = bits.Mul64(p.h2, p.s1)
	lo, c = bits.Add64(lo, l, 0)
	hi += h + c
	d0hi, d0lo := hi, lo

	hi, lo = bits.Mul64(p.h0, p.r1)
	h, l = bits.Mul64(p.h1, p.r0)
	lo, c = bits.Add64(lo, l, 0)
	hi += h + c
	h, l = bits.Mul64(p.h2, p.s2)
	lo, c = bits.Add64(lo, l, 0)
	hi += h + c
	d1hi, d1lo := hi, lo

	hi, lo = bits.Mul64(p.h0, p.r2)
	h, l = bits.Mul64(p.h1, p.r1)
	lo, c = bits.Add64(lo, l, 0)
	hi += h + c
	h, l = bits.Mul64(p.h2, p.r0)
	lo, c = bits.Add64(lo, l, 0)
	hi += h + c
	d2hi, d2lo := hi, lo

	// Carry propagation across the 44-bit limbs.
	carry := shiftRight44(d0hi, d0lo)
	p.h0 = d0lo & 0xfffffffffff
	d1lo, c = bits.Add64(d1lo, carry, 0)
	d1hi += c
	carry = shiftRight44(d1hi, d1lo)
	p.h1 = d1lo & 0xfffffffffff
	d2lo, c = bits.Add64(d2lo, carry, 0)
	d2hi += c
	carry = shiftRight42(d2hi, d2lo)
	p.h2 = d2lo & 0x3ffffffffff
	p.h0 += carry * 5
	p.h1 += p.h0 >> 44
	p.h0 &= 0xfffffffffff
}

func shiftRight44(hi, lo uint64) uint64 { return lo>>44 | hi<<20 }
func shiftRight42(hi, lo uint64) uint64 { return lo>>42 | hi<<22 }

func (p *poly1305) Write(m []byte) {
	if p.n > 0 {
		want := 16 - p.n
		if want > len(m) {
			want = len(m)
		}
		copy(p.buf[p.n:], m[:want])
		p.n += want
		m = m[want:]
		if p.n < 16 {
			return
		}
		p.blocks(p.buf[:], 1)
		p.n = 0
	}
	if n := len(m) - len(m)%16; n > 0 {
		p.blocks(m[:n], 1)
		m = m[n:]
	}
	if len(m) > 0 {
		p.n = copy(p.buf[:], m)
	}
}

func (p *poly1305) Sum(out *[16]byte) {
	if p.n > 0 {
		var b [16]byte
		copy(b[:], p.buf[:p.n])
		b[p.n] = 1
		p.blocks(b[:], 0)
		p.n = 0
	}
	h0, h1, h2 := p.h0, p.h1, p.h2

	// Final carry, then conditionally subtract 2^130-5.
	c := h1 >> 44
	h1 &= 0xfffffffffff
	h2 += c
	c = h2 >> 42
	h2 &= 0x3ffffffffff
	h0 += c * 5
	c = h0 >> 44
	h0 &= 0xfffffffffff
	h1 += c

	g0, b := bits.Sub64(h0, 0xffffffffffb, 0)
	g1, b := bits.Sub64(h1, 0xfffffffffff, b)
	g2, b := bits.Sub64(h2, 0x3ffffffffff, b)
	// b == 0 means h >= 2^130-5, so use the reduced value.
	mask := b - 1
	h0 = h0&^mask | g0&mask
	h1 = h1&^mask | g1&mask
	h2 = h2&^mask | g2&mask

	lo := h0 | h1<<44
	hi := h1>>20 | h2<<24

	// h += pad (the second half of the key), mod 2^128.
	lo, c = bits.Add64(lo, binary.LittleEndian.Uint64(p.pad[0:8]), 0)
	hi, _ = bits.Add64(hi, binary.LittleEndian.Uint64(p.pad[8:16]), c)

	binary.LittleEndian.PutUint64(out[0:8], lo)
	binary.LittleEndian.PutUint64(out[8:16], hi)
}

// polyPad writes the zero padding that aligns an AEAD component to 16 bytes.
func polyPad(p *poly1305, n int) {
	if rem := n % 16; rem != 0 {
		var zeros [16]byte
		p.Write(zeros[:16-rem])
	}
}

func aeadTag(key, nonce, ciphertext, additionalData []byte) [16]byte {
	var polyKey [32]byte
	XORKeyStream(polyKey[:], polyKey[:], key, nonce, 0)
	p := newPoly1305(polyKey[:])
	p.Write(additionalData)
	polyPad(p, len(additionalData))
	p.Write(ciphertext)
	polyPad(p, len(ciphertext))
	var lens [16]byte
	binary.LittleEndian.PutUint64(lens[0:8], uint64(len(additionalData)))
	binary.LittleEndian.PutUint64(lens[8:16], uint64(len(ciphertext)))
	p.Write(lens[:])
	var tag [16]byte
	p.Sum(&tag)
	return tag
}

// Seal encrypts and authenticates plaintext, appending the result to dst.
func Seal(dst, key, nonce, plaintext, additionalData []byte) []byte {
	if len(key) != KeySize {
		panic("aead: bad key size")
	}
	if len(nonce) != NonceSize {
		panic("aead: bad nonce size")
	}
	ret, out := sliceForAppend(dst, len(plaintext)+TagSize)
	XORKeyStream(out[:len(plaintext)], plaintext, key, nonce, 1)
	tag := aeadTag(key, nonce, out[:len(plaintext)], additionalData)
	copy(out[len(plaintext):], tag[:])
	return ret
}

// Open authenticates and decrypts ciphertext, appending the plaintext to dst.
func Open(dst, key, nonce, ciphertext, additionalData []byte) ([]byte, error) {
	if len(key) != KeySize {
		panic("aead: bad key size")
	}
	if len(nonce) != NonceSize {
		panic("aead: bad nonce size")
	}
	if len(ciphertext) < TagSize {
		return nil, ErrOpen
	}
	body, tag := ciphertext[:len(ciphertext)-TagSize], ciphertext[len(ciphertext)-TagSize:]
	want := aeadTag(key, nonce, body, additionalData)
	if subtle.ConstantTimeCompare(want[:], tag) != 1 {
		return nil, ErrOpen
	}
	ret, out := sliceForAppend(dst, len(body))
	XORKeyStream(out, body, key, nonce, 1)
	return ret, nil
}

func sliceForAppend(in []byte, n int) (head, tail []byte) {
	if total := len(in) + n; cap(in) >= total {
