func TestPoly1305(t *testing.T) {
	key := unhex(t, "85d6be7857556d337f4452fe42d506a8010380afb0db2fd4abff6af4149f51b")
	key = append([]byte{}, unhex(t, "85d6be7857556d337f4452fe42d506a8010380afb0db2fd4abff6af4149f51b0")...)
