	// Adjust: RFC value ends in ...f5:1b, with a leading 0x01 03 80 8a fb...
	k = unhex(t, "85d6be7857556d337f4452fe42d506a8"+"0103808afb0db2fd4abff6af4149f51b")
	p := newPoly1305(k)
	p.Write([]byte("Cryptographic Forum Research Group"))
	var tag [16]byte
