func TestPoly1305Incremental(t *testing.T) {
	k := unhex(t, "85d6be7857556d337f4452fe42d506a80103808afb0db2fd4abff6af4149f51b")
	msg := []byte("Cryptographic Forum Research Group")
	for _, split := range []int{1, 3, 7, 15, 16, 17, 31, 33} {
