// Package kdf implements the key derivation functions age needs: HKDF
// (RFC 5869), PBKDF2 (RFC 8018) and scrypt (RFC 7914).
package kdf

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/binary"
	"errors"
	"hash"
	"math"
)

// HKDF derives n bytes from secret using the extract-then-expand construction
// with the given salt and info, over SHA-256.
func HKDF(secret, salt, info []byte, n int) []byte {
	prk := hkdfExtract(secret, salt)
	return hkdfExpand(prk, info, n)
}

func hkdfExtract(secret, salt []byte) []byte {
	if salt == nil {
		salt = make([]byte, sha256.Size)
	}
	m := hmac.New(sha256.New, salt)
	m.Write(secret)
	return m.Sum(nil)
}

func hkdfExpand(prk, info []byte, n int) []byte {
	out := make([]byte, 0, n)
	var prev []byte
	m := hmac.New(sha256.New, prk)
	for counter := byte(1); len(out) < n; counter++ {
		if counter == 0 {
			panic("kdf: HKDF output too long")
		}
		m.Reset()
		m.Write(prev)
		m.Write(info)
		m.Write([]byte{counter})
		prev = m.Sum(prev[:0])
		out = append(out, prev...)
	}
	return out[:n]
}

// PBKDF2 implements PBKDF2 with the given PRF hash.
func PBKDF2(password, salt []byte, iter, keyLen int, h func() hash.Hash) []byte {
	prf := hmac.New(h, password)
	hashLen := prf.Size()
	numBlocks := (keyLen + hashLen - 1) / hashLen

	var buf [4]byte
	dk := make([]byte, 0, numBlocks*hashLen)
	u := make([]byte, hashLen)
	for block := 1; block <= numBlocks; block++ {
		prf.Reset()
		prf.Write(salt)
		binary.BigEndian.PutUint32(buf[:], uint32(block))
		prf.Write(buf[:])
		dk = prf.Sum(dk)
		t := dk[len(dk)-hashLen:]
		copy(u, t)
		for n := 2; n <= iter; n++ {
			prf.Reset()
			prf.Write(u)
			u = prf.Sum(u[:0])
			for i := range u {
				t[i] ^= u[i]
			}
		}
	}
	return dk[:keyLen]
}

// salsaXOR sets out = salsa20/8(in XOR tmp) and copies the result back to tmp,
// operating on 64-byte blocks held as 16 little-endian words.
func salsaXOR(tmp *[16]uint32, in, out []byte) {
	w := [16]uint32{}
	for i := 0; i < 16; i++ {
		w[i] = tmp[i] ^ binary.LittleEndian.Uint32(in[i*4:])
	}
	x := w
	rotl := func(v uint32, n uint) uint32 { return v<<n | v>>(32-n) }
	for i := 0; i < 4; i++ {
		// Column rounds.
		x[4] ^= rotl(x[0]+x[12], 7)
		x[8] ^= rotl(x[4]+x[0], 9)
		x[12] ^= rotl(x[8]+x[4], 13)
		x[0] ^= rotl(x[12]+x[8], 18)
		x[9] ^= rotl(x[5]+x[1], 7)
		x[13] ^= rotl(x[9]+x[5], 9)
		x[1] ^= rotl(x[13]+x[9], 13)
		x[5] ^= rotl(x[1]+x[13], 18)
		x[14] ^= rotl(x[10]+x[6], 7)
		x[2] ^= rotl(x[14]+x[10], 9)
		x[6] ^= rotl(x[2]+x[14], 13)
		x[10] ^= rotl(x[6]+x[2], 18)
		x[3] ^= rotl(x[15]+x[11], 7)
		x[7] ^= rotl(x[3]+x[15], 9)
		x[11] ^= rotl(x[7]+x[3], 13)
		x[15] ^= rotl(x[11]+x[7], 18)
		// Row rounds.
		x[1] ^= rotl(x[0]+x[3], 7)
		x[2] ^= rotl(x[1]+x[0], 9)
		x[3] ^= rotl(x[2]+x[1], 13)
		x[0] ^= rotl(x[3]+x[2], 18)
		x[6] ^= rotl(x[5]+x[4], 7)
		x[7] ^= rotl(x[6]+x[5], 9)
		x[4] ^= rotl(x[7]+x[6], 13)
		x[5] ^= rotl(x[4]+x[7], 18)
		x[11] ^= rotl(x[10]+x[9], 7)
		x[8] ^= rotl(x[11]+x[10], 9)
		x[9] ^= rotl(x[8]+x[11], 13)
		x[10] ^= rotl(x[9]+x[8], 18)
		x[12] ^= rotl(x[15]+x[14], 7)
		x[13] ^= rotl(x[12]+x[15], 9)
		x[14] ^= rotl(x[13]+x[12], 13)
		x[15] ^= rotl(x[14]+x[13], 18)
	}
	for i := 0; i < 16; i++ {
		tmp[i] = w[i] + x[i]
		binary.LittleEndian.PutUint32(out[i*4:], tmp[i])
	}
}

// blockMix is the scryptBlockMix function of RFC 7914, section 4.
func blockMix(tmp *[16]uint32, in, out []byte, r int) {
	copy(tmp[:], asWords(in[(2*r-1)*64:]))
	for i := 0; i < 2*r; i += 2 {
		salsaXOR(tmp, in[i*64:], out[i/2*64:])
		salsaXOR(tmp, in[i*64+64:], out[i/2*64+r*64:])
	}
}

func asWords(b []byte) []uint32 {
	w := make([]uint32, 16)
	for i := range w {
		w[i] = binary.LittleEndian.Uint32(b[i*4:])
	}
	return w
}

// integerify returns the last 64-byte block of b interpreted as a
// little-endian integer, as required by ROMix.
func integerify(b []byte, r int) uint64 {
	return binary.LittleEndian.Uint64(b[(2*r-1)*64:])
}

// romix is the SMix function of RFC 7914, section 5.
func romix(b []byte, r, n int, v, xy []byte) {
	x := xy[:128*r]
	y := xy[128*r:]
	var tmp [16]uint32

	copy(x, b)
	for i := 0; i < n; i += 2 {
		copy(v[i*(128*r):], x)
		blockMix(&tmp, x, y, r)
		copy(v[(i+1)*(128*r):], y)
		blockMix(&tmp, y, x, r)
	}
	for i := 0; i < n; i += 2 {
		j := int(integerify(x, r) & uint64(n-1))
		xorBytes(x, v[j*(128*r):(j+1)*(128*r)])
		blockMix(&tmp, x, y, r)
		j = int(integerify(y, r) & uint64(n-1))
		xorBytes(y, v[j*(128*r):(j+1)*(128*r)])
		blockMix(&tmp, y, x, r)
	}
	copy(b, x)
}

func xorBytes(dst, src []byte) {
	for i := range dst {
		dst[i] ^= src[i]
	}
}

// Scrypt derives a keyLen-byte key from password and salt using the scrypt
// parameters n (which must be a power of two greater than 1), r and p.
func Scrypt(password, salt []byte, n, r, p, keyLen int) ([]byte, error) {
	if n <= 1 || n&(n-1) != 0 {
		return nil, errors.New("scrypt: N must be > 1 and a power of 2")
	}
	if r <= 0 || p <= 0 {
		return nil, errors.New("scrypt: invalid r or p")
	}
	if uint64(r)*uint64(p) >= 1<<30 || r > math.MaxInt/128/p || r > math.MaxInt/256 ||
		n > math.MaxInt/128/r {
		return nil, errors.New("scrypt: parameters are too large")
	}

	b := PBKDF2(password, salt, 1, p*128*r, sha256.New)
	v := make([]byte, 32*n*r)
	xy := make([]byte, 256*r)
	for i := 0; i < p; i++ {
		romix(b[i*128*r:(i+1)*128*r], r, n, v, xy)
	}
	return PBKDF2(password, b, 1, keyLen, sha256.New), nil
}

